function search(nums, target) {
  let lo = 0, hi = nums.length - 1 //@init
  while (lo <= hi) { //@loop
    const mid = (lo + hi) >> 1 //@mid
    if (nums[mid] === target) return mid //@found
    if (nums[mid] < target) lo = mid + 1 //@right
    else hi = mid - 1 //@left
  }
  return -1 //@none
}

